import { detectPlateObjects, modelNameOf } from './object-labels';

/** A plate G-code whose Klipper defines name these objects, followed by the first print move. */
function klipperPlate(names: string[]): Buffer {
  return Buffer.from(
    [
      '; generated by OrcaSlicer 2.4.2',
      ...names.map((n) => `EXCLUDE_OBJECT_DEFINE NAME=${n} CENTER=110,110 POLYGON=[[100,100],[120,100],[120,120],[100,120]]`),
      'EXCLUDE_OBJECT_START NAME=' + names[0],
      'G1 X100 Y100 E1',
    ].join('\n'),
  );
}

describe('detectPlateObjects: CLI clones (name_1 … name_N)', () => {
  it('groups fish.stl_1..fish.stl_12 as one model x12 and still counts 12 units', () => {
    const r = detectPlateObjects(klipperPlate(Array.from({ length: 12 }, (_, i) => `fish.stl_${i + 1}`)));
    expect(r.objectCount).toBe(12);
    expect(r.objectModels).toEqual([{ model: 'fish', count: 12 }]);
    expect(r.objectLabelSource).toBe('klipper');
    expect(r.ignoredLabels).toEqual([]);
  });

  it('leaves a lone bracket_2 as the model bracket_2', () => {
    const r = detectPlateObjects(klipperPlate(['bracket_2']));
    expect(r.objectCount).toBe(1);
    expect(r.objectModels).toEqual([{ model: 'bracket 2', count: 1 }]);
    expect(modelNameOf('bracket_2')).toBe('bracket 2');
  });

  it('groups foo_1, foo_2 as foo x2 and keeps bar x1', () => {
    const r = detectPlateObjects(klipperPlate(['foo_1', 'foo_2', 'bar']));
    expect(r.objectCount).toBe(3);
    expect(r.objectModels).toEqual([
      { model: 'foo', count: 2 },
      { model: 'bar', count: 1 },
    ]);
  });

  it('does not strip a _N tail that is shared by only one label next to an unrelated model', () => {
    const r = detectPlateObjects(klipperPlate(['bracket_2', 'lid']));
    expect(r.objectCount).toBe(2);
    expect(r.objectModels).toEqual([
      { model: 'bracket 2', count: 1 },
      { model: 'lid', count: 1 },
    ]);
  });

  it('groups CLI _N clones and GUI id:N copy M copies of one model together on a mixed plate', () => {
    // Klipper labels carry no spaces: the GUI form there is name_id_N_copy_M.
    const r = detectPlateObjects(
      klipperPlate(['fish.stl_1', 'fish.stl_2', 'fish.stl_3', 'fish_id_0_copy_0', 'fish_id_0_copy_1', 'lid.stl_1', 'lid.stl_2']),
    );
    expect(r.objectCount).toBe(7);
    expect(r.objectModels).toEqual([
      { model: 'fish', count: 5 },
      { model: 'lid', count: 2 },
    ]);
  });

  it('never reads the copy number of a Klipper GUI label (…_copy_0) as a clone number', () => {
    const r = detectPlateObjects(klipperPlate(['sarindes_base_v2_id_3_copy_0', 'sarindes_base_v2_id_3_copy_1']));
    expect(r.objectCount).toBe(2);
    expect(r.objectModels).toEqual([{ model: 'sarindes base v2', count: 2 }]);
  });
});

describe('detectPlateObjects: GUI copies (regression guard)', () => {
  it('groups Klipper id_N_copy_M labels by model', () => {
    const r = detectPlateObjects(
      klipperPlate([
        'sarindes_base_v2_id_3_copy_0',
        'sarindes_base_v2_id_3_copy_1',
        'sarindes_base_v2_id_3_copy_2',
        'lid_id_4_copy_0',
      ]),
    );
    expect(r.objectCount).toBe(4);
    expect(r.objectModels).toEqual([
      { model: 'sarindes base v2', count: 3 },
      { model: 'lid', count: 1 },
    ]);
  });

  it('strips Orca "id:N copy M" and Prusa "Shape.stl id:N copy M" suffixes', () => {
    expect(modelNameOf('sarindes base v2 id:3 copy 0')).toBe('sarindes base v2');
    expect(modelNameOf('Shape-Box.stl id:0 copy 2')).toBe('Shape-Box');
  });

  it('reads "; printing object" comments when there are no Klipper or Marlin labels', () => {
    const buf = Buffer.from(
      ['; printing object Shape-Box.stl id:0 copy 0', 'G1 X1', '; printing object Shape-Box.stl id:0 copy 1', 'G1 X2'].join('\n'),
    );
    const r = detectPlateObjects(buf);
    expect(r.objectCount).toBe(2);
    expect(r.objectModels).toEqual([{ model: 'Shape-Box', count: 2 }]);
    expect(r.objectLabelSource).toBe('comment');
  });

  it('ignores the purge tower and reports an unlabelled file as unknown', () => {
    const r = detectPlateObjects(klipperPlate(['Wipe_Tower', 'cube_id_1_copy_0']));
    expect(r.objectCount).toBe(1);
    expect(r.ignoredLabels).toEqual(['Wipe_Tower']);
    expect(detectPlateObjects(Buffer.from('G1 X1 Y1\n')).objectCount).toBeNull();
  });
});
